package com.idfc.ai.runbook.confluence; import com.idfc.ai.runbook.config.RunbookProperties; import org.springframework.stereotype.Component;
@Component public class ConfluencePublisher { private final RunbookProperties props; private final RunbookTargetRegistry targets; public ConfluencePublisher(RunbookProperties p,RunbookTargetRegistry t){props=p;targets=t;} public String publish(String service,String mode,String body){if(!props.getConfluence().isEnabled())throw new IllegalStateException("RUNBOOK_PUBLISH_FAILED: Confluence disabled");var target=targets.target(service);String page="TEST".equals(mode)?target.getTestPageId():"PRODUCTION".equals(mode)?target.getProductionPageId():null;if(page==null||props.getConfluence().getProtectedPageIds().contains(page))throw new IllegalArgumentException("RUNBOOK_TARGET_PROTECTED");if(body.getBytes(java.nio.charset.StandardCharsets.UTF_8).length<props.getValidation().getMinimumRenderedBytes())throw new IllegalArgumentException("RUNBOOK_RENDER_FAILED");return page;} }
